using CatalogService.Data; using CatalogService.Models; using Microsoft.EntityFrameworkCore;
var builder = WebApplication.CreateBuilder(args); builder.Services.AddDbContext<CatalogDbContext>(o => o.UseSqlServer(builder.Configuration.GetConnectionString("CatalogDb"))); builder.Services.AddControllers(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(); builder.Services.AddCors(o => o.AddDefaultPolicy(p => p.WithOrigins(builder.Configuration.GetSection("Cors:Origins").Get<string[]>() ?? []).AllowAnyHeader().AllowAnyMethod()));
var app = builder.Build(); app.UseExceptionHandler("/error"); app.MapGet("/error", () => Results.Problem()).ExcludeFromDescription(); app.UseSwagger(); app.UseSwaggerUI(); app.UseHttpsRedirection(); app.UseCors(); app.MapControllers();
using (var scope = app.Services.CreateScope()) { var db = scope.ServiceProvider.GetRequiredService<CatalogDbContext>(); await db.Database.EnsureCreatedAsync(); if (!await db.Products.AnyAsync()) { db.Products.AddRange(new Product { Slug="vela-ambar", Name="Vela Ámbar", Price=480, Existencia=12, Category="Aromas", ImageUrl="https://images.unsplash.com/photo-1603006905003-be475563bc59?auto=format&fit=crop&w=700&q=85", Description="Cera vegetal y notas cálidas de ámbar." }, new Product { Slug="taza-arena", Name="Taza Arena", Price=290, Existencia=8, Category="Mesa", ImageUrl="https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?auto=format&fit=crop&w=700&q=85", Description="Cerámica esmaltada hecha para las pausas largas." }); await db.SaveChangesAsync(); } }
app.Run(); public partial class Program { }
